void setup_memory(uint32_t ap) {
    mem.clear();
    a_pages = ap;

    // Extended 1-level DDT at 0x10000, stride 64. DID10 -> 0x10280, DID11 -> 0x102C0.
    write64(0x10280, 0x0000000000000001ULL);
    write64(0x10288, 0x0000000000000000ULL);
    write64(0x10290, 0x000000000000A000ULL);
    write64(0x10298, 0x8000000000000020ULL); // Sv39, V root 0x20000
    write64(0x102A0, 0x0ULL); write64(0x102A8, 0x0ULL);
    write64(0x102B0, 0x0ULL); write64(0x102B8, 0x0ULL);

    write64(0x102C0, 0x0000000000000001ULL);
    write64(0x102C8, 0x0000000000000000ULL);
    write64(0x102D0, 0x000000000000B000ULL);
    write64(0x102D8, 0x8000000000000030ULL); // Sv39, A root 0x30000
    write64(0x102E0, 0x0ULL); write64(0x102E8, 0x0ULL);
    write64(0x102F0, 0x0ULL); write64(0x102F8, 0x0ULL);

    // V page tables: root 0x20000, L1V 0x40000, L0V 0x50000.
    write64(0x20000, 0x0000000000010001ULL);
    write64(0x40400, 0x0000000000014001ULL);
    write64(0x50000, 0x00000000200000DFULL); // Vsrc -> 0x80000000
    write64(0x50008, 0x00000000200004DFULL); // Vdst -> 0x80001000
    write64(0x50010, ((V_COLD_DST_PA >> 12) << 10) | 0xDFULL); // Vcold-dst -> 0x80002000

    // A page tables: root 0x30000, L1A 0x60000, L0A 0x70000.
    write64(0x30000, 0x0000000000018001ULL);
    write64(0x60800, 0x000000000001C001ULL);
    for (uint32_t n = 0; n < 2 * a_pages; ++n) {
        uint64_t pa = (n < a_pages)
                    ? (A_SRC_PA_BASE + (uint64_t)n * 0x1000)
                    : (A_DST_PA_BASE + (uint64_t)(n - a_pages) * 0x1000);
        write64(0x70000 + (uint64_t)n * 8, ((pa >> 12) << 10) | 0xDFULL);
    }

    // V source content + unique destination pre-fill.
    for (uint32_t i = 0; i < PAGE_BEATS; ++i) {
        write64(V_SRC_PA + (uint64_t)i * 8, page_word(0, i));
        write64(V_DST_PA + (uint64_t)i * 8, page_old(0, i));
        write64(V_COLD_DST_PA + (uint64_t)i * 8, page_old(0, i));
    }
    // A source content + unique destination pre-fill.
    for (uint32_t p = 0; p < a_pages; ++p) {
        for (uint32_t i = 0; i < PAGE_BEATS; ++i) {
            write64(A_SRC_PA_BASE + (uint64_t)p * 0x1000 + (uint64_t)i * 8,
                    page_word(1 + p, i));
            write64(A_DST_PA_BASE + (uint64_t)p * 0x1000 + (uint64_t)i * 8,
                    page_old(1 + p, i));
        }

// ---- SYSTEM mode: ONE shared DDR port (comp + DS merged by the xbar) ----
// The plain DDR model latency applies uniformly to every accepted DDR read;
// the real 50/50 DS delayer adds latency on the DS path in RTL only.
void drive_ddr() {
    ddr_setup_wait = false;
    ddr_model_empty = mem_q.empty();
    top->ddr_aw_ready = 1;
    top->ddr_w_ready  = 1;
    if (write_tail_pause != 0 && !caw_q.empty()) {
        CawEnt& c = caw_q.front();
        if (((c.id >> 4) & 3u) == 2u && c.len == 255 && c.got == 248 && !c.tail_hold_seen) {
            c.tail_hold_seen = true;
            c.tail_release_cycle = g_cycle + write_tail_pause;
            ++write_tail_holds;
            trace_event("ddr_w_tail_hold", c.id, c.addr, write_tail_pause);
        }
        if (c.tail_hold_seen && g_cycle < c.tail_release_cycle) {
            top->ddr_w_ready = 0;
            ++write_tail_hold_cycles;
        }
    }
    top->ddr_ar_ready = (mem_q.size() < 16) ? 1 : 0;
    if (!cb_q.empty()) {
        top->ddr_b_valid = 1;
        top->ddr_b_id    = (uint8_t)cb_q.front();
        top->ddr_b_resp  = 0;
    } else {
        top->ddr_b_valid = 0;
        top->ddr_b_id    = 0;
        top->ddr_b_resp  = 0;
    }

    top->ddr_r_valid = 0;
    if (mem_q.empty()) return;
    // AXI allows R interleaving across different IDs. Promote only the
    // oldest DS request, retaining order within every ID and preserving
    // a VALID payload held from the prior tick. No DUT arbitration changes.
    // Each request retains its original latency/beat state after rotation.
    // The priority WINDOW is the legacy first-V-issue window in the legacy
    // path and the full-era V-completion count in full-batch mode
    // (v_transfers == 64 in the approved full configuration).  The held-R
    // guard applies to BOTH: a beat currently held MUST NOT be displaced.
    const bool ds_window = full_batch
        ? (full_era && full_done_n[0] < (uint32_t)v_transfers)
        : win_open;
    if (ds_priority && !ddr_r_held && ds_window &&
        ((mem_q.front().id >> 4) & 3) != 3) {
        auto ds = std::find_if(mem_q.begin(), mem_q.end(), [](const MemRead& r) {
            return ((r.id >> 4) & 3) == 3;
        });
        if (ds != mem_q.end()) std::rotate(mem_q.begin(), ds, ds + 1);
    }
    MemRead& h = mem_q.front();
    ddr_setup_port = (h.id >> 4) & 3u;
    if (read_latency_overlap && measurement_phase) {
        // Same isolated-request delay as the old model: AR accepted at
        // t first returns at t + latency + 1. Queued requests age from
        // acceptance, allowing their preparation delays to overlap.
        if (g_cycle <= h.accepted_cycle + (long)ptw_latency) {
            ddr_setup_wait = true;
            return;
        }
    } else if (h.latency > 0) {
        --h.latency;
        ddr_setup_wait = true;
        return;
    }

    top->ddr_r_valid = 1;
    top->ddr_r_data  = read64(h.addr + (uint64_t)h.beat * 8);
    top->ddr_r_id    = (uint8_t)h.id;   // 6-bit shared-DDR ID echoed verbatim
    top->ddr_r_resp  = 0;
    top->ddr_r_last  = (h.beat == h.len) ? 1 : 0;
}

#ifdef ACTUAL_DMA_SYSTEM
        ddr_r_held = s_ddr_r_held;
        if (f_ddr_ar) {
            ++n_ddr_ar;
            ++n_slv_ar[(s_ddr_ar_i >> 4) & 3];
            // full-batch: real payload read bytes for the completion master
            // (slave port 2).  DS walk (3) and CPU (0) are excluded.
            if (full_era && (((s_ddr_ar_i >> 4) & 3u) == 2u)) {
                const unsigned ch = (unsigned)((s_ddr_ar_i >> 2) & 1u);
                ++full_ar_n[ch];
                full_rd_bytes[ch] += ((uint64_t)s_ddr_ar_l + 1ULL) * 8ULL;
            }
            MemRead r; r.port = P_DDR; r.addr = s_ddr_ar_a;
            r.len = (uint8_t)s_ddr_ar_l; r.id = (uint8_t)s_ddr_ar_i;
            r.beat = 0; r.latency = (int)ptw_latency;
            r.accepted_cycle = g_cycle;
            mem_q.push_back(r);
        }

}
if (f_ddr_r) {
    ++n_ddr_r;
    CHECK(!mem_q.empty(), "R handshake with an empty DDR read queue");
    MemRead& h = mem_q.front();
    CHECK(h.port == P_DDR, "R handshake on an unexpected port");
    // The R payload driven this cycle must match the queue head: the
    // id is echoed verbatim and LAST marks the burst tail.
    CHECK((uint32_t)top->ddr_r_id == (uint32_t)h.id &&
          ((h.beat == h.len) == (top->ddr_r_last != 0)),
          "DDR R id/LAST does not match the queued request head");
    // full-batch: accepted-AR -> R byte conservation (slave port 2).
    if (full_era && ((((uint8_t)h.id) >> 4) & 3u) == 2u) {
        const unsigned chn = (unsigned)((((uint8_t)h.id) >> 2) & 1u);
        // Payload range: only the completion source pages may count.
        const uint64_t a1 = h.addr + ((uint64_t)h.len + 1ULL) * 8ULL - 1ULL;
        CHECK((h.addr >> 12) == (a1 >> 12),
              "full-batch AR payload crosses a 4 KiB page");
        const bool in_v = (h.addr >= V_SRC_PA &&
                           a1 <  V_SRC_PA + (uint64_t)PAGE_BYTES);
        const bool in_a = (h.addr >= A_SRC_PA_BASE &&
                           a1 <  A_SRC_PA_BASE + (uint64_t)a_pages * 0x1000ULL);
        CHECK(chn == 0 ? in_v : in_a,
              "full-batch AR payload outside its channel source map");
        ++full_r_n[chn];
        full_r_return_bytes[chn] += 8ULL;   // one 64-bit R beat
        if (top->ddr_r_resp != 0) ++full_err[chn];
    }
    if (h.beat == h.len) mem_q.pop_front();
    else                 h.beat++;
}

void reset(bool enable) {
    nonblock_enable = enable;
    top->clk_i  = 0;
    top->rst_ni = 0;

    cfg_valid = false; cfg_write = false; cfg_sel = false;
    cfg_addr = 0; cfg_wdata = 0; cfg_wstrb = 0;

    mem_q.clear(); caw_q.clear(); cb_q.clear();

for (int i = 0; i < 8; ++i) tick();
top->rst_ni = 1;
for (int i = 0; i < 4; ++i) tick();
last_progress_cycle = g_cycle;

    void check_quiet(const char* tag) {
        // Quiet requires BOTH the translation-request port to be fully idle
        // (TL in_flight == 0) AND both DMAs to report job_quiet (2'b11 == 3).
        // Not quiet is a hard failure, never a silent pass.
        const long QUIET_TIMEOUT = 200000L;
        bool quiet = false;
        for (long i = 0; i < QUIET_TIMEOUT; ++i) {
            tick();
#ifdef ACTUAL_DMA_SYSTEM
            const bool cpu_q = top->dbg_cpu_quiet && top->dbg_cpu_wr_quiet;
#else
            const bool cpu_q = true;
#endif
            if (top->dbg_in_flight == 0 && top->dbg_dma_job_quiet == 3 && cpu_q) {
                quiet = true;
                break;
            }
            if (g_cycle - last_progress_cycle > WATCHDOG_CYCLES) {
                dump_stall(std::string("quiet ") + tag);
                throw TestFailure("watchdog during drain-to-quiet");
            }
#ifdef ACTUAL_DMA_SYSTEM
            if (cpu_enable && cpu_writes && !top->dbg_cpu_wr_quiet &&
                (g_cycle - cpu_wr_progress_cycle > cpu_wr_watchdog_cycles)) {
                dump_stall(std::string("quiet cpu-wr ") + tag);
                throw TestFailure("watchdog: synthetic CPU write/AMO made no progress");
            }
#endif
        }
        if (!quiet) {
            dump_stall(std::string("quiet-not-reached ") + tag);
            throw TestFailure("not quiet: TL in_flight!=0 or DMA job_quiet!=3");
        }
        CHECK(mem_q.empty() && caw_q.empty() && cb_q.empty(),
              "memory/AW queues not empty after drain");
        (void)tag;

// Enable the hardware overlap scoreboard before the first cfg write
// so the initial A issue pulse is captured.
warm_hw_track = true;

// ---- A-first initial launch (idma.c:2497-2501) -------------------
a_id = warm_submit_a();
a_in_flight = true;

// ---- V first submit, before the poll loop (idma.c:706) ----------
v_id = warm_submit_v();
v_in_flight = true;

for (;;) {
    // Bounded watchdog refreshed ONLY by a V (DMA0) completion, so A
    // handshakes can never mask a stalled V.
    if (g_cycle - warm_v_progress_cycle > WARM_V_WATCHDOG_CYCLES) {
        dump_stall("warm V progress");
        throw TestFailure("watchdog: warm V made no completion progress");
    }
    if (g_cycle - scenario_start > scenario_budget) {
        dump_stall("warm budget");
        throw TestFailure("scenario budget exceeded during warm-up");
    }

    // ---- V first: poll (idma.c:718), then refill (idma.c:727) -----
    if (v_in_flight && cfg_rd(SEL_V, REG_DONE) == v_id) {
        v_in_flight = false;
        ++warm_v_completed;
        warm_v_progress_cycle = g_cycle;
        // idma.c:722-726: stop at exactly `count` completions, before
        // A is polled or refilled again.
        if (warm_v_completed == warmup)
            break;
        v_id = warm_submit_v();
        v_in_flight = true;
    }

    // ---- A second: poll (idma.c:731), refill (idma.c:736) --------
    if (a_in_flight && cfg_rd(SEL_A, REG_DONE) == a_id) {
        a_in_flight = false;
        ++warm_a_completed;
        a_id = warm_submit_a();
        a_in_flight = true;
    }

    tick();
}

CHECK(!v_in_flight, "warm V still in flight after the target count");
CHECK(warm_v_completed == warmup,
      "warm V completion count does not match --warmup");
CHECK(warm_v_submitted == warmup,
      "warm issued more V transfers than the target count");

// ---- drain the still-open A transfer (idma.c:2524-2528) ---------
// A fixed cycle cap keeps this bound independent of any progress
// heuristic, like idma_drain()'s fixed timeout.
drain_start = g_cycle;
if (a_in_flight) {
    a_deadline = g_cycle + WARM_A_DRAIN_CYCLES;
    for (;;) {
        if (cfg_rd(SEL_A, REG_DONE) == a_id) {
            a_in_flight = false;
            ++warm_a_completed;   // count the drained job
            break;
        }
        if (g_cycle >= a_deadline) {
            dump_stall("warm A drain");
            throw TestFailure("watchdog: warm A drain never completed");
        }
        tick();
    }
}
warm_a_drain_cycles = g_cycle - drain_start;
warm_a_drained      = true;
warm_end_cycle      = g_cycle;

// Disable the hardware scoreboard now that warm is done.
warm_hw_track = false;

// ---- post-warm consistency and data checks ----------------------
CHECK(warm_a_completed == warm_a_submitted,
      "warm A completion count does not match submissions after drain");
CHECK(warm_a_completed > 0, "warm A completed no transfer");
CHECK(warm_hw_v_issue == warm_hw_v_done,
      "warm hardware V issue/done pulses disagree");
CHECK(warm_hw_a_issue == warm_hw_a_done,
      "warm hardware A issue/done pulses disagree");
CHECK(!warm_hw_v_busy && !warm_hw_a_busy,
      "warm hardware job still pending after drain");

setup_memory(a_pages);
// Repeated-scenario hygiene: enter with the owner-only measurement
// phase OFF so the reset ticks and the whole warm phase drive
// owner_only_i low.  Warm caches and already-selected requests are
// untouched.
measurement_phase = false;
reset(enable);
scenario_start      = g_cycle;
last_progress_cycle = g_cycle;
v_progress_cycle    = g_cycle;

// ---- 1. warm + drain -------------------------------------------
warm_phase();
drain_a();

// ---- 2. configure BOTH batches before any trigger --------------
// A autonomous: ring over a_pages, no gap.
configure_batch(SEL_A, A_IOVA_BASE,
                A_IOVA_BASE + (uint64_t)a_pages * 0x1000,
                a_target, a_pages, 0);
// V victim: single page, --transfers jobs, --v-gap gap.
configure_batch(SEL_V, V_SRC_IOVA, v_measure_dst_iova(),
                (uint64_t)v_transfers, 1, v_gap_cycles);

// ---- 3. launches + run to terminal -----------------------------
// Full-batch (independent, default OFF) shares the configure phase
// above.  Its common t0 is captured inside run_full_batch() after
// BOTH batches are configured and before the first NEXT_ID.
if (full_batch) {
    run_full_batch(name, enable);
} else {

void run_full_batch(const char* name, bool enable) {
    (void)name;
    (void)enable;
    full_measure_begin();

    // Billed common delay after t0 and before the first NEXT_ID.  t0 is
    // NOT moved by any delay; the delay is only billed into the budget.
    for (uint32_t i = 0; i < start_delay; ++i) {
        tick(); full_check_started_lanes();
    }

    // launch-order av/va selects which channel's NEXT_ID comes first; the
    // per-channel delays are bounded and purely acceptance.  Every delay
    // loop still polices every lane that already started, so a long delay
    // cannot skip the watchdog of a started lane.
    if (launch_order == "va") {
        for (uint32_t i = 0; i < v_start_delay; ++i) {
            tick(); full_check_started_lanes();
        }
        start_batch(SEL_V); full_started[0] = true; full_last_progress[0] = g_cycle;
        for (uint32_t i = 0; i < a_start_delay; ++i) {
            tick(); full_check_started_lanes();
        }
        start_batch(SEL_A); full_started[1] = true; full_last_progress[1] = g_cycle;
    } else {
        for (uint32_t i = 0; i < a_start_delay; ++i) {
            tick(); full_check_started_lanes();
        }
        start_batch(SEL_A); full_started[1] = true; full_last_progress[1] = g_cycle;
        for (uint32_t i = 0; i < v_start_delay; ++i) {
            tick(); full_check_started_lanes();
        }
        start_batch(SEL_V); full_started[0] = true; full_last_progress[0] = g_cycle;
    }

        if (v_done && a_done) break;
    }

    // Both channels completed NATURALLY: STOP is never used on the
    // measured path in full mode.
    check_quiet(name);
    full_quiet_cycle = g_cycle;
    full_measure_end();
    full_reg_cross_check();
}

// Read-back cross-check.  Times in the summary come ONLY from the
// pre-edge hardware pulses; these registers/flags are counts only.
void full_reg_cross_check() {
    // Register readback is a CROSS-CHECK only.  It happens AFTER the
    // protocol quiet moment was captured (check_quiet) and its idle
    // transaction overhead is therefore EXCLUDED from every reported time.

    std::string mode     = "s";
    uint32_t    a_pages  = 8;
    uint32_t    v_gap    = 1000;
    uint32_t    transfers= 64;
    uint32_t    warmup   = 256;
    uint32_t    ptw_lat  = 31;
    uint64_t    a_target = 1048576ULL;
    bool        v_cold_dst = false;
    bool        owner_only = false;
    // ---- full-batch independent mode (default OFF) ----------------------
    bool        full_batch    = false;
    bool        cpu_enable    = true;
    uint32_t    start_delay   = 0;
    uint32_t    v_start_delay = 0;
    uint32_t    a_start_delay = 0;
    std::string launch_order  = "av";
    long        full_watchdog = 200000L;
#ifdef ACTUAL_DMA_SYSTEM
    bool        cpu_writes = false;
    bool        ds_priority = false;
    uint32_t    write_tail_pause = 0;
    bool        read_latency_overlap = false;
    std::string trace_path;
    std::string read_admit = "none";
    uint32_t    read_budget = 256;
    uint32_t    read_period = 256;
    bool        read_admit_measure_only = false;
#endif

if (const char* v = val("transfers")) transfers = (uint32_t)std::strtoul(v, nullptr, 0);
if (const char* v = val("warmup"))    warmup = (uint32_t)std::strtoul(v, nullptr, 0);
if (const char* v = val("ptw-latency")) ptw_lat = (uint32_t)std::strtoul(v, nullptr, 0);
if (const char* v = val("a-target"))  a_target = std::strtoull(v, nullptr, 0);
if (const char* v = val("v-cold-dst")) {
    char* end = nullptr;
    const unsigned long parsed = std::strtoul(v, &end, 0);
    if (end == v || *end != '\0' || parsed > 1) {
        std::fprintf(stderr,
            "nonblock_actual_dma_test: invalid +v-cold-dst='%s' (expected 0|1)\n", v);
        return 2;
    }
    v_cold_dst = (parsed != 0);
}
if (const char* v = val("owner-only")) {
    char* end = nullptr;
    const unsigned long parsed = std::strtoul(v, &end, 0);
    if (end == v || *end != '\0' || parsed > 1) {
        std::fprintf(stderr,
            "nonblock_actual_dma_test: invalid +owner-only='%s' (expected 0|1)\n", v);
        return 2;
    }
    owner_only = (parsed != 0);
}
if (const char* v = val("full-batch")) {
    if (!parse_gate01("full-batch", v, full_batch)) return 2;
}
if (const char* v = val("cpu-enable")) {
    if (!parse_gate01("cpu-enable", v, cpu_enable)) return 2;
}

        if (const char* v = val("start-delay")) {
            unsigned long long p = 0;
            if (!parse_ulong("start-delay", v, p, 0xFFFFFFFFULL)) return 2;
            start_delay = (uint32_t)p;
        }
        if (const char* v = val("v-start-delay")) {
            unsigned long long p = 0;
            if (!parse_ulong("v-start-delay", v, p, 0xFFFFFFFFULL)) return 2;
            v_start_delay = (uint32_t)p;
        }
        if (const char* v = val("a-start-delay")) {
            unsigned long long p = 0;
            if (!parse_ulong("a-start-delay", v, p, 0xFFFFFFFFULL)) return 2;
            a_start_delay = (uint32_t)p;
        }
        if (const char* v = val("full-watchdog")) {
            unsigned long long p = 0;
            if (!parse_ulong("full-watchdog", v, p, 0x7FFFFFFFFFFFFFFFULL) || p == 0) {
                std::fprintf(stderr,
                    "nonblock_actual_dma_test: +full-watchdog must be > 0\n");
                return 2;
            }
            full_watchdog = (long)p;
        }
        if (const char* v = val("launch-order")) launch_order = v;
#ifdef ACTUAL_DMA_SYSTEM
        if (const char* v = val("cpu-writes")) {
            if (!parse_gate01("cpu-writes", v, cpu_writes)) return 2;
        }
        if (const char* v = val("ds-priority")) {
            if (!parse_gate01("ds-priority", v, ds_priority)) return 2;
        }
        if (const char* v = val("write-tail-pause")) write_tail_pause = (uint32_t)std::strtoul(v, nullptr, 0);
        if (const char* v = val("read-latency-model")) {
            const std::string m = v;
            if (m != "serial" && m != "overlap") {
                std::fprintf(stderr, "nonblock_actual_dma_test: +read-latency-model must be serial|overlap\n");
                return 2;
            }
            read_latency_overlap = (m == "overlap");
        }
        if (const char* v = val("event-trace")) trace_path = v;
        if (const char* v = val("read-admit"))  read_admit = v;
        if (const char* v = val("read-budget")) read_budget = (uint32_t)std::strtoul(v, nullptr, 0);
        if (const char* v = val("read-period")) read_period = (uint32_t)std::strtoul(v, nullptr, 0);
        if (const char* v = val("read-admit-measure-only")) {

    if (launch_order != "av" && launch_order != "va") {
        std::fprintf(stderr,
            "nonblock_actual_dma_test: invalid +launch-order='%s' (expected av|va)\n",
            launch_order.c_str());
        return 2;
    }
    if (start_delay > 2000000u || v_start_delay > 2000000u || a_start_delay > 2000000u) {
        std::fprintf(stderr, "launch delays must be <= 2000000 cycles\n");
        return 2;
    }
    if (!full_batch && (start_delay || v_start_delay || a_start_delay || launch_order != "av" || full_watchdog != 200000L)) {
        std::fprintf(stderr, "launch delays/order/watchdog require full-batch\n");
        return 2;
    }
    if (full_watchdog <= 0) {
        std::fprintf(stderr, "nonblock_actual_dma_test: +full-watchdog must be > 0\n");
        return 2;
    }
#ifndef ACTUAL_DMA_SYSTEM
    if (full_batch) {
        std::fprintf(stderr,
            "nonblock_actual_dma_test: +full-batch requires the SYSTEM build (--system)\n");
        return 2;
    }
#endif
#ifdef ACTUAL_DMA_SYSTEM
    if (full_batch) {
        if (!(transfers == 64 && a_target == 64ULL && v_gap == 0 &&
              (a_pages == 1 || a_pages == 8) && warmup == 256 && ptw_lat == 31)) {
            std::fprintf(stderr,
                "nonblock_actual_dma_test: +full-batch requires transfers=64 "
                "a-target=64 v-gap=0 a-pages=1|8 warmup=256 ptw-latency=31\n");
            return 2;
        }
        // Full-batch does not support the completion-AR proxy profiles.  Fail
        // loudly instead of silently ignoring the request.
        if (read_admit != "none") {
            std::fprintf(stderr,
                "nonblock_actual_dma_test: +full-batch does not support "
                "+read-admit (got '%s')\n", read_admit.c_str());
            return 2;
        }
    }

// The wrapper forwards --mode into the run-time nonblock_enable_i and
// policy_partition_i inputs.  policy_partition_i is only effective in a
// build elaborated with -GPolicyEnable=1; tests/test_nonblock_actual_dma.py
// adds that define (and an own object directory) for p / pn only.
//   s  -> Nonblock = 0, policy_partition = 0
//   n  -> Nonblock = 1, policy_partition = 0
//   p  -> Nonblock = 0, policy_partition = 1
//   pn -> Nonblock = 1, policy_partition = 1
const bool enable = (mode == "n" || mode == "pn");
const bool policy = (mode == "p" || mode == "pn");

assign req_ready = (debug_resp_valid_o & debug_resp_ready_i) |
                   (slow_resp_valid & slow_resp_ready) |
                   (ats_trans_resp_valid_o & ats_trans_resp_ready_i) ;

assign ddtc_lu          = (state_q == DDT) | ats_ddtc_valid_i | n_ddtc_lu;
assign ddtc_lu_did      = n_ddtc_lu ? n_ddtc_did :
                         ats_ddtc_valid_i ? ats_ddtc_did_i : req_data.did;
assign ddtc_lu_hit = cache_ddtc_hit && !n_ddtc_lu;
assign ats_ddtc_ready_o = ~ddtc_lu_hit;

assign iotlb_lu         = (state_q == PT) | (state_q == MSI) | n_iotlb_lu;
assign iotlb_lu_vpn     = n_iotlb_lu ? n_iotlb_vpn : req_data.iova[rv_iommu::GPLEN39-1:12];
assign iotlb_lu_pscid   = n_iotlb_lu ? n_iotlb_pscid : pscid_q;
assign iotlb_lu_gscid   = n_iotlb_lu ? '0 : gscid_q;
assign cache_iotlb_en1 = n_iotlb_lu ? 1'b1 : en_1S_q;
assign cache_iotlb_en2 = n_iotlb_lu ? 1'b0 : en_2S_q;
assign iotlb_lu_hit = cache_iotlb_hit && !n_iotlb_lu;
assign iotlb_update     = (msi_iotlb_update.update) ?
                          (msi_iotlb_update) :
                          (ptw_iotlb_update);

// Two lifecycle tags (one outstanding request per bank), one response port.
// A rejected probe never handshakes: the original arbiter later accepts it.
assign normal_gate = !NonblockEnable ||
                     (state_q == IDLE && !req_valid && !n_intercept);
assign trans_req_ready_o = n_intercept ? n_accept : (normal_trans_ready && normal_gate);
assign nonblock_fire_o = n_accept;
assign nonblock_busy_o = n_busy;
// All lifecycle storage must be empty; incoming VALID also excludes a
// same-edge configuration. Never reset or discard a pending response.
assign policy_quiet_o = state_q == IDLE && !req_valid && !arb_req_valid &&
    !trans_req_valid_i && !ats_trans_req_valid_i && !debug_req_valid_i &&
    !ats_ddtc_valid_i && !n_busy && !n_intercept && !n_accept &&
    !fast_resp_valid && !slow_resp_valid && !ats_trans_resp_valid_o &&
    !debug_resp_valid_o && !fault_valid_o && !e3_ptw_active &&
    !ddtw_axi_req_o.ar_valid && !pdtw_axi_req_o.ar_valid &&
    !ptw_axi_req_o.ar_valid && !msiptw_axi_req_o.ar_valid &&
    !ddtw_axi_resp_i.r_valid && !pdtw_axi_resp_i.r_valid &&
    !ptw_axi_resp_i.r_valid && !msiptw_axi_resp_i.r_valid &&
    !iotlb_update.update && !ddtc_update.update &&
    !iotinval_i.inval_vma && !iotinval_i.inval_gvma &&
    !iodirinval_i.inval_ddtc && !iodirinval_i.inval_pdtc;
assign n_window = state_q == PT && e3_ptw_active && en_1S_q &&
                  !en_2S_q && !ddt_imp_trans_q && !pdt_imp_trans_q &&
                  !req_data.is_debug && trans_req_data_i.bank != req_data.bank &&
                  !ats_ddtc_valid_i && !debug_req_valid_i && !ats_trans_req_valid_i;
assign nonblock_diag_o = {n_diag[15:1],
    (state_q == PT && e3_ptw_active && en_1S_q && !en_2S_q)};
if (NonblockEnable) begin : gen_nonblock_hit
    rv_iommu_nonblock_hit #(
        .PAddrWidth(PLEN),
        .HasMsiContext(RVIOMMUCfg.MSITrans != rv_iommu_cfg::MSI_DISABLED),
        .dc_t(dc_t), .req_t(trans_req_data_t),
        .resp_t(trans_resp_data_t), .ddtp_t(iommu_reg2hw_ddtp_reg_t)
    ) i_hit (
        .clk_i, .rst_ni, .enable_i(nonblock_enable_i),
        .window_i(n_window),
        .candidate_i(trans_req_data_i), .candidate_valid_i(trans_req_valid_i),
        .normal_fire_i(trans_req_valid_i && normal_trans_ready && normal_gate),
        .invalidate_i(iotinval_i.inval_vma || iotinval_i.inval_gvma ||
                      iodirinval_i.inval_ddtc || iodirinval_i.inval_pdtc),
        .ddtp_i(ddtp_i), .intercept_o(n_intercept), .accept_o(n_accept),
        .busy_o(n_busy), .ddtc_lookup_o(n_ddtc_lu), .ddtc_touch_o(n_ddtc_touch),
        .ddtc_did_o(n_ddtc_did), .ddtc_hit_i(cache_ddtc_hit), .ddtc_dc_i(ddtc_dc),
        .iotlb_lookup_o(n_iotlb_lu), .iotlb_touch_o(n_iotlb_touch),
        .iotlb_vpn_o(n_iotlb_vpn), .iotlb_pscid_o(n_iotlb_pscid),
        .iotlb_hit_i(cache_iotlb_hit), .iotlb_content_i(iotlb_lu_content),
        .response_o(fast_resp_data), .response_valid_o(fast_resp_valid),
        .response_ready_i(fast_resp_ready), .diag_o(n_diag)
    );
end else begin : gen_no_nonblock_hit
    assign n_diag = '0;
    assign n_intercept = 0;
    assign n_accept = 0;
    assign n_busy = 0;
    assign n_ddtc_lu = 0;
    assign n_ddtc_touch = 0;
    assign n_ddtc_did = '0;
    assign n_iotlb_lu = 0;
    assign n_iotlb_touch = 0;
    assign n_iotlb_vpn = '0;
    assign n_iotlb_pscid = '0;
    assign fast_resp_data = '0;
    assign fast_resp_valid = 0;
end
stream_arbiter #(.DATA_T(trans_resp_data_t), .N_INP(2), .ARBITER("rr"))
    i_nonblock_response_arbiter (
        .clk_i, .rst_ni, .inp_data_i({fast_resp_data, slow_resp_data}),
        .inp_valid_i({fast_resp_valid, slow_resp_valid}),
        .inp_ready_o({fast_resp_ready, slow_resp_ready}),
        .oup_data_o(trans_resp_data_o), .oup_valid_o(trans_resp_valid_o),
        .oup_ready_i(trans_resp_ready_i)
    );

// IOTLB lookup and PTW Walk
PT: begin

    msi_1S_data_n = msi_1S_content;

    // Signal PT Walk if occurred
    hpm_events_o.valid              = ~iotlb_lu_hit;
    hpm_events_o.etype_msk          = (rv_iommu::hpm_etype_mask_t'(1) << rv_iommu::IOTLB_MISS) |
                                      (rv_iommu::hpm_etype_mask_t'(en_1S_q) << rv_iommu::S1_PTW) |
                                      (rv_iommu::hpm_etype_mask_t'(en_2S_q) << rv_iommu::S2_PTW);
    hpm_events_o.filters.gscid_v    = 1'b1;
    hpm_events_o.filters.pscid_v    = 1'b1;

    /*
      A Page Table Walk may end in:
        (1) Error;
        (2) Successful implicit 2nd-stage translation;
        (3) MSI GPA;
        (4) IOTLB update and hit
    */

    // (1) PTW error
    if (ptw_error) begin
        error_2S_n      = ptw_error_2S;
        error_2S_int_n  = ptw_error_2S_int;
        error_gpaddr_n  = ptw_bad_gpaddr;
        error_code_n    = ptw_cause;
        state_n         = (dc_q.tc.dtf) ?
                            (COMPLETE) :
                            (ERROR);
    end

    // (2) Implicit 2nd-stage translation completed
    if (imp_done) begin
        if (ddt_imp_trans_q) begin
            ddt_imp_trans_n = 1'b0;
            state_n         = DDT;
        end
        else if (pdt_imp_trans_q) begin
            pdt_imp_trans_n = 1'b0;
            state_n         = PDT;
        end
    end

    // (3) GPA is MSI address
    if (gpaddr_is_msi) begin
        state_n = MSI;
    end

    // (4) IOTLB hit
    if (iotlb_lu_hit) begin
        state_n         = COMPLETE;
        is_superpage_n  = iotlb_lu_content.content_1S.is_2M |
                          iotlb_lu_content.content_1S.is_1G |
                          iotlb_lu_content.content_2S.is_2M |

// Translation completion
COMPLETE: begin

    // Debug translation
    if (req_data.is_debug) begin
        debug_resp_valid_o  = 1'b1;
        if (debug_resp_ready_i) begin
            state_n = IDLE;
        end
    end
    // ATS transltion
    else if(req_data.ttype == rv_iommu::PCIE_ATS_TRANS_REQ) begin
        ats_trans_resp_valid_o  = 1'b1;
        if (ats_trans_resp_ready_i) begin
            state_n = IDLE;
        end
    end
    // Normal translation
    else begin
        slow_resp_valid  = 1'b1;
        if (slow_resp_ready) begin
            state_n = IDLE;
        end
    end

typedef enum logic [2:0] {IDLE, DC, LEAF, OUT, REJECT} state_t;
state_t state_q;
req_t req_q;
dc_t dc_q;
ddtp_t ddtp_q;
resp_t resp_q;
logic start, dc_ok, leaf_ok, msi_safe, msi_leaf_safe;
logic probe_stable;
logic is_write, is_read, canonical;
localparam int unsigned PPNW = PAddrWidth - 12;

assign start = state_q == IDLE && enable_i && window_i &&
               candidate_valid_i && !invalidate_i;
assign busy_o = state_q != IDLE && state_q != REJECT;
assign intercept_o = start || busy_o;
assign ddtc_lookup_o = state_q == DC || state_q == LEAF;
assign ddtc_did_o = req_q.did;
assign iotlb_lookup_o = state_q == LEAF;
assign iotlb_vpn_o = req_q.iova[GPLEN39-1:12];
assign iotlb_pscid_o = dc_q.ta.pscid;
assign is_write = req_q.ttype == UNTRANSLATED_W;
assign is_read = req_q.ttype == UNTRANSLATED_R;
assign canonical = req_q.iova[63:39] == {25{req_q.iova[38]}};

// The actual cached DC belongs to this request. No active-walker context
// or saved inferred PSCID is used. All excluded cases fall through.
if (HasMsiContext) begin : gen_msi_guard
  // Flat MSI can coexist with ordinary S1 copies. Exclude both the input
  // range and the cached S1 GPA range, using the normal TL/PTW match widths.
  // Reads are conservatively excluded too; MSI/reserved modes fall through.
  logic input_is_msi, leaf_is_msi;
  assign input_is_msi =
      (req_q.iova[VLEN39-1:12] & ~ddtc_dc_i.msi_addr_mask.mask[VPNW39-1:0]) ==
      (ddtc_dc_i.msi_addr_pattern.pattern[VPNW39-1:0] &
       ~ddtc_dc_i.msi_addr_mask.mask[VPNW39-1:0]);
  assign leaf_is_msi =
      (iotlb_content_i.content_1S.ppn[GPPNW39-1:0] &
       ~dc_q.msi_addr_mask.mask[GPPNW39-1:0]) ==
      (dc_q.msi_addr_pattern.pattern[GPPNW39-1:0] &
       ~dc_q.msi_addr_mask.mask[GPPNW39-1:0]);
  assign msi_safe = ddtc_dc_i.msiptp.mode == 0 ||
                   (ddtc_dc_i.msiptp.mode == 1 && !input_is_msi);
  assign msi_leaf_safe = dc_q.msiptp.mode == 0 ||
                        (dc_q.msiptp.mode == 1 && !leaf_is_msi);
end else begin : gen_no_msi
  assign msi_safe = 1'b1;
  assign msi_leaf_safe = 1'b1;
end
assign dc_ok = msi_safe && ddtc_hit_i && ddtc_dc_i.tc.v &&
    !ddtc_dc_i.tc.pdtv && !ddtc_dc_i.tc.sxl &&
    !ddtc_dc_i.tc.t2gpa && !ddtc_dc_i.tc.en_ats &&
    !ddtc_dc_i.tc.en_pri && !req_q.pid_valid && !req_q.priv &&
    !req_q.is_debug && (is_write || is_read) && canonical &&
    ddtc_dc_i.fsc.mode == ModeSv39 &&
    ddtc_dc_i.iohgatp.mode == ModeBare &&
    ((ddtp_i.iommu_mode.q == 2 && req_q.did[23:6] == 0) ||
     (ddtp_i.iommu_mode.q == 3 && req_q.did[23:15] == 0) ||
     ddtp_i.iommu_mode.q == 4);
assign leaf_ok = msi_leaf_safe && iotlb_hit_i && iotlb_content_i.content_1S.v &&
    iotlb_content_i.content_1S.u &&
    !iotlb_content_i.content_1S.is_1G &&
    !iotlb_content_i.content_1S.is_2M &&
    (is_write ? iotlb_content_i.content_1S.w :
                iotlb_content_i.content_1S.r);
assign accept_o = state_q == LEAF && enable_i &&
    candidate_valid_i && candidate_i == req_q &&
    !invalidate_i && ddtp_i == ddtp_q && dc_ok &&
    ddtc_dc_i == dc_q && leaf_ok;
// Probes do not change replacement state; only an actually accepted hit
// touches both real caches, exactly once.
assign ddtc_touch_o = accept_o;
assign iotlb_touch_o = accept_o;
assign response_o = resp_q;
assign response_valid_o = state_q == OUT;

assign probe_stable = enable_i && candidate_valid_i && candidate_i == req_q &&
                      !invalidate_i && ddtp_i == ddtp_q;

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    state_q <= IDLE;
    req_q <= '0;
    dc_q <= '0;
    ddtp_q <= '0;
    resp_q <= '0;
  end else begin
    case (state_q)
      IDLE: if (start) begin
        req_q <= candidate_i;
        ddtp_q <= ddtp_i;
        state_q <= DC;
      end
      DC: begin
        if (!enable_i || invalidate_i || ddtp_i != ddtp_q ||
            !dc_ok || !candidate_valid_i || candidate_i != req_q)
          state_q <= REJECT;
        else begin
          dc_q <= ddtc_dc_i;
          state_q <= LEAF;
        end
      end
      LEAF: begin
        if (accept_o) begin
          resp_q <= '0;
          resp_q.bank <= req_q.bank;
          resp_q.spaddr <= {iotlb_content_i.content_1S.ppn[PPNW-1:0],
                            req_q.iova[11:0]};
          resp_q.r <= iotlb_content_i.content_1S.r;
          resp_q.w <= iotlb_content_i.content_1S.w;
          resp_q.x <= iotlb_content_i.content_1S.x;
          resp_q.u <= iotlb_content_i.content_1S.u;
          resp_q.g <= iotlb_content_i.content_1S.g;
          state_q <= OUT;
        end else state_q <= REJECT;
      end
      OUT: if (response_ready_i) state_q <= IDLE;
      REJECT: if (normal_fire_i || !candidate_valid_i) state_q <= IDLE;
      default: state_q <= IDLE;
    endcase
  end
end

ptw_state_t state_q, state_n;

