    .inp_ready_o    ({ddtw_resp_o.ar_ready, pdtw_resp_o.ar_ready, ptw_resp_o.ar_ready, cq_resp_o.ar_ready, pq_resp_o.ar_ready, msiptw_resp_o.ar_ready, mrif_handler_resp_o.ar_ready}),
